-- What a fresh 12.1.0.0 database grants before anything else runs: the database authorities,
-- PUBLIC's privileges per catalog view, the row and column access controls, PUBLIC's modules,
-- the packages db2-node sends dynamic SQL through, and which SYS schemas an administrator can create in.
SELECT VARCHAR(GRANTEE, 12) AS GRANTEE, CONNECTAUTH, CREATETABAUTH, BINDADDAUTH, IMPLSCHEMAAUTH, DBADMAUTH FROM SYSCAT.DBAUTH ORDER BY 1;
SELECT VARCHAR(TABSCHEMA, 10) AS TABSCHEMA, COUNT(*) AS N, MAX(SELECTAUTH) AS S, MAX(INSERTAUTH) AS I, MAX(UPDATEAUTH) AS U, MAX(DELETEAUTH) AS D, MAX(CONTROLAUTH) AS C FROM SYSCAT.TABAUTH WHERE GRANTEE = 'PUBLIC' GROUP BY TABSCHEMA ORDER BY 1;
SELECT VARCHAR(TABNAME, 24) AS SYSSTAT_UPDATE_TO_PUBLIC FROM SYSCAT.TABAUTH WHERE GRANTEE = 'PUBLIC' AND TABSCHEMA = 'SYSSTAT' AND UPDATEAUTH <> 'N' ORDER BY 1;
SELECT VARCHAR(SCHEMANAME, 10) AS SCHEMANAME, ALTERINAUTH, CREATEINAUTH, DROPINAUTH FROM SYSCAT.SCHEMAAUTH WHERE GRANTEE = 'PUBLIC' ORDER BY 1;
SELECT VARCHAR(SCHEMA, 10) AS SCHEMA, ROUTINETYPE, COUNT(*) AS N FROM SYSCAT.ROUTINEAUTH WHERE GRANTEE = 'PUBLIC' GROUP BY SCHEMA, ROUTINETYPE ORDER BY 1, 2;
SELECT VARCHAR(a.SPECIFICNAME, 20) AS PUBLIC_EXECUTES, VARCHAR(r.OWNER, 8) AS OWNER, r.OWNERTYPE FROM SYSCAT.ROUTINEAUTH a JOIN SYSCAT.ROUTINES r ON r.ROUTINESCHEMA = a.SCHEMA AND r.SPECIFICNAME = a.SPECIFICNAME WHERE a.GRANTEE = 'PUBLIC' AND a.SCHEMA = 'SYSPROC' AND r.ROUTINENAME IN ('ADMIN_CMD', 'SYSTS_ADMIN_CMD', 'ADMIN_TASK_ADD', 'ADMIN_TASK_UPDATE', 'SNAP_WRITE_FILE', 'REMOTE_QUERY', 'DB2LOAD') ORDER BY 1;
SELECT VARCHAR(m.MODULESCHEMA, 10) AS MODULESCHEMA, VARCHAR(m.MODULENAME, 22) AS MODULENAME, VARCHAR(m.OWNER, 8) AS OWNER, m.OWNERTYPE, CASE WHEN EXISTS (SELECT 1 FROM SYSCAT.MODULEAUTH a WHERE a.MODULEID = m.MODULEID AND a.GRANTEE = 'PUBLIC') THEN 'Y' ELSE 'N' END AS PUBLIC_EXECUTES FROM SYSCAT.MODULES m WHERE m.MODULESCHEMA = 'SYSIBMADM' ORDER BY 2;
SELECT VARCHAR(p.PKGSCHEMA, 8) AS PKGSCHEMA, p.OWNERTYPE, p.BOUNDBYTYPE, p.DYNAMICRULES, COUNT(*) AS N, MAX(a.BINDAUTH) AS PUBLIC_BIND, MAX(a.EXECUTEAUTH) AS PUBLIC_EXECUTE FROM SYSCAT.PACKAGES p LEFT JOIN SYSCAT.PACKAGEAUTH a ON a.PKGSCHEMA = p.PKGSCHEMA AND a.PKGNAME = p.PKGNAME AND a.GRANTEE = 'PUBLIC' GROUP BY p.PKGSCHEMA, p.OWNERTYPE, p.BOUNDBYTYPE, p.DYNAMICRULES ORDER BY 1, 4;
SELECT VARCHAR(PKGNAME, 10) AS DRIVER_PACKAGE, OWNERTYPE, BOUNDBYTYPE, DYNAMICRULES FROM SYSCAT.PACKAGES WHERE PKGSCHEMA = 'NULLID' AND PKGNAME IN ('SYSSH200', 'SYSLH200') ORDER BY 1;
SELECT VARCHAR(SEQSCHEMA, 10) AS SEQSCHEMA, COUNT(*) AS PUBLIC_SEQUENCE_GRANTS FROM SYSCAT.SEQUENCEAUTH WHERE GRANTEE = 'PUBLIC' GROUP BY SEQSCHEMA;
SELECT VARCHAR(VARNAME, 26) AS VARNAME, READAUTH, WRITEAUTH FROM SYSCAT.VARIABLEAUTH WHERE GRANTEE = 'PUBLIC' AND WRITEAUTH <> 'N' ORDER BY 1;
SELECT VARCHAR(GRANTEE, 10) AS GRANTEE, GRANTEETYPE, VARCHAR(ROLENAME, 16) AS ROLENAME, ADMIN FROM SYSCAT.ROLEAUTH ORDER BY 3;
SELECT VARCHAR(CONTROLNAME, 48) AS CONTROLNAME, VARCHAR(OWNER, 8) AS OWNER, OWNERTYPE, CONTROLTYPE FROM SYSCAT.CONTROLS ORDER BY 1;
SELECT OWNERTYPE, COUNT(*) AS ROUTINES FROM SYSCAT.ROUTINES GROUP BY OWNERTYPE ORDER BY 1;
CREATE FUNCTION SYSPROC.LIBREDB_PROBE () RETURNS INTEGER LANGUAGE SQL RETURN 1;
CREATE TABLE SYSCAT.LIBREDB_PROBE (ID INTEGER);
CREATE TABLE SYSIBMADM.LIBREDB_PROBE (ID INTEGER);
CREATE FUNCTION SYSTOOLS.LIBREDB_PROBE () RETURNS INTEGER LANGUAGE SQL RETURN 1;
SELECT VARCHAR(ROUTINESCHEMA, 10) AS ROUTINESCHEMA, VARCHAR(ROUTINENAME, 16) AS ROUTINENAME, VARCHAR(OWNER, 10) AS OWNER, OWNERTYPE FROM SYSCAT.ROUTINES WHERE ROUTINENAME = 'LIBREDB_PROBE';
DROP FUNCTION SYSTOOLS.LIBREDB_PROBE;
